select id, supplier from jsh_supplier
where id = #{id}
and ifnull(delete_flag,'0') !='1'

select * from jsh_supplier
where type = #{type}
and ifnull(delete_flag,'0') !='1'

    and contacts = #{contacts}


    and (
        telephone like concat('%', #{telephone}, '%')
        or phone_num like concat('%', #{telephone}, '%')
    )



        and 1=0


limit 1

select * from jsh_supplier
where type = '会员'
and ifnull(delete_flag,'0') !='1'
and (
    1 = 0

        or contacts = #{contacts}




                or replace(replace(replace(replace(replace(ifnull(telephone,''), ' ', ''), '-', ''), '+', ''), '(', ''), ')', '') like concat('%', #{phone}, '%')
                or replace(replace(replace(replace(replace(ifnull(phone_num,''), ' ', ''), '-', ''), '+', ''), '(', ''), ')', '') like concat('%', #{phone}, '%')




        or wechat_account = #{wechatAccount}


        or douyin_account = #{douyinAccount}


        or alipay_account = #{alipayAccount}


        or other_account = #{otherAccount}

)
order by id desc
limit 100
